// Get the dashboard ID from the previous node
const dashboardId = $input.first().json.id;
const charts = $('Extract Dashboard Config').first().json.dashboardConfig.cards;

// For each chart in the dashboard config, create a card
const items = [];

for (let i = 0; i < charts.length; i++) {
  const chart = charts[i];

  // Create a query first
  const queryPayload = {
    url: 'http://metabase-api:3000/api/card',
    method: 'POST',
    headers: {
      'X-Metabase-Session': $secret.METABASE_SESSION_TOKEN
    },
    body: {
      name: chart.name,
      display: chart.type,
      visualization_settings: {
        'graph.dimensions': chart.dimensions,
        'graph.metrics': chart.metrics
      },
      dataset_query: {
        type: 'native',
        native: {
          query: chart.query
        },
        database: 1 // Assuming DuckDB is database ID 1
      },
      description: chart.description
    }
  };

  items.push({ json: queryPayload });
}

return items;

// Get all the created cards
const cards = $input.all().map(item => item.json);
const dashboardId = $('Create Metabase Dashboard').first().json.id;

// For each card, add it to the dashboard
const items = [];

for (let i = 0; i < cards.length; i++) {
  const card = cards[i];

  // Position cards in a grid
  const row = Math.floor(i / 2);
  const col = i % 2;

  const dashboardCardPayload = {
    url: `http://metabase-api:3000/api/dashboard/${dashboardId}/cards`,
    method: 'POST',
    headers: {
      'X-Metabase-Session': $secret.METABASE_SESSION_TOKEN
    },
    body: {
      cardId: card.id,
      row: row * 4,
      col: col * 6,
      sizeX: 6,
      sizeY: 4
    }
  };

  items.push({ json: dashboardCardPayload });
}

return items;

// JavaScript code node solution
const inputData = $input.all();
const results = [];

try {
  // Check if we have valid input
  if (inputData.length === 0) {
    throw new Error("No input data received");
  }

  // Get the first item from the input
  const item = inputData[0];

  // Different ways the data might be structured
  let outputData;

  if (item.json && item.json.output) {
    outputData = item.json.output;
  } else if (item.json && Array.isArray(item.json) && item.json[0] && item.json[0].output) {
    outputData = item.json[0].output;
  } else if (item.output) {
    outputData = item.output;
  } else if (Array.isArray(item) && item[0] && item[0].output) {
    outputData = item[0].output;
  } else {
    outputData = item.json || item;
  }

  // Access files from outputData
  const files = outputData.files || [];

  // Filter Python files
  const pythonFiles = files.filter(file => file.filename && file.filename.endsWith('.py'));

  // Sort by sequence
  pythonFiles.sort((a, b) => (a.sequence || 0) - (b.sequence || 0));

  // If no Python files found, return an error
  if (pythonFiles.length === 0) {
    results.push({
      json: {
        error: "No Python files found in the output"
      }
    });
  } else {
    // Process each Python file
    for (const file of pythonFiles) {
      // Generate a timestamp for the pipeline ID
      const timestamp = new Date().toISOString().replace(/[-:T.Z]/g, '').substring(0, 14);
      const sequence = file.sequence || 0;

      // Create HTTP request body directly
      const requestBody = {
        pipelineId: `${timestamp}_${sequence}`,
        code: file.content || '',
        options: {
          saveToFile: true,
          executeNow: true
        }
      };

      results.push({ 
        json: {
          requestBody: requestBody,
          metadata: {
            filename: file.filename || `script_${sequence}.py`,
            description: file.description || '',
            sequence: sequence
          }
        } 
      });
    }
  }
} catch (error) {
  console.log(`Error processing data: ${error.message}`);
  results.push({
    json: {
      error: `Error processing data: ${error.message}`,
      original_data: JSON.stringify(inputData)
    }
  });
}

return results;

